  function km(a, b, c, d) { const x = Math.sin(rad(c - a) / 2) ** 2 + Math.cos(rad(a)) * Math.cos(rad(c)) * Math.sin(rad(d - b) / 2) ** 2; return 12742 * Math.asin(Math.sqrt(x)); }
  o.textContent += km(18.52, 73.86, 19.07, 72.88).toFixed(0) + ' km (Haversine)';
